package com.gamehub.application.controller; import com.gamehub.application.service.TeamService; import java.util.List; public final class TeamController {private final TeamService service;public TeamController(TeamService s){service=s;}public List<String> teams()throws Exception{return service.teams();}public List<String> requests(long c)throws Exception{return service.requests(c);}public long create(long c,String n)throws Exception{return service.create(c,n);}public void request(long t,long c)throws Exception{service.request(t,c);}public void decide(long c,long t,long m,boolean ok)throws Exception{service.decide(c,t,m,ok);}}